-- Final schema for the SQLite backend, consolidated from the Postgres
-- migrations 0001..0007. Differences from Postgres:
--   * uuid  -> TEXT (32-char lowercase hex, generated by internal/ids)
--   * timestamptz -> TEXT (fixed-width UTC RFC3339Nano; lexicographic order
--     equals chronological order, so range predicates work as-is)
--   * text[] -> TEXT holding a JSON array (api_tokens.scopes)
--   * no file_events table (dropped in Postgres 0007; never written)
--   * no column defaults for timestamps: every writer passes an explicit value

CREATE TABLE users (
    id                  TEXT PRIMARY KEY,
    username            TEXT NOT NULL,
    password_hash       TEXT NOT NULL,
    role                TEXT NOT NULL CHECK (role IN ('admin', 'user')),
    default_visibility  TEXT NOT NULL DEFAULT 'public'
        CHECK (default_visibility IN ('public', 'private')),
    created_at          TEXT NOT NULL,
    updated_at          TEXT NOT NULL,
    password_changed_at TEXT NOT NULL
);

CREATE UNIQUE INDEX users_username_idx ON users (username);

CREATE TABLE sessions (
    id           TEXT PRIMARY KEY,
    user_id      TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash   TEXT NOT NULL,
    expires_at   TEXT NOT NULL,
    created_at   TEXT NOT NULL,
    user_agent   TEXT NOT NULL DEFAULT '',
    ip           TEXT NOT NULL DEFAULT '',
    last_seen_at TEXT NOT NULL
);

CREATE UNIQUE INDEX sessions_token_hash_idx ON sessions (token_hash);
CREATE INDEX sessions_user_id_idx ON sessions (user_id);

CREATE TABLE files (
    id                      TEXT PRIMARY KEY,
    name                    TEXT NOT NULL,
    size                    INTEGER NOT NULL,
    chunk_size              INTEGER NOT NULL,
    created_at              TEXT NOT NULL,
    views                   INTEGER NOT NULL DEFAULT 0,
    downloads               INTEGER NOT NULL DEFAULT 0,
    ranges                  INTEGER NOT NULL DEFAULT 0,
    bytes_served            INTEGER NOT NULL DEFAULT 0,
    unique_visitors         INTEGER NOT NULL DEFAULT 0,
    last_access_at          TEXT,
    owner_user_id           TEXT REFERENCES users (id) ON DELETE SET NULL,
    visibility              TEXT NOT NULL DEFAULT 'public'
        CHECK (visibility IN ('public', 'private')),
    access_token_hash       TEXT,
    access_token_rotated_at TEXT,
    expires_at              TEXT NOT NULL,
    status                  TEXT NOT NULL DEFAULT 'ready'
        CHECK (status IN ('ready', 'reused')),
    password_hash           TEXT,
    max_downloads           INTEGER
        CHECK (max_downloads IS NULL OR max_downloads > 0),
    download_count          INTEGER NOT NULL DEFAULT 0,
    share_mode              TEXT NOT NULL DEFAULT 'download'
        CHECK (share_mode IN ('view', 'download')),
    sha256                  TEXT
);

CREATE INDEX files_created_at_idx ON files (created_at DESC);
CREATE INDEX files_owner_created_idx ON files (owner_user_id, created_at DESC);
CREATE INDEX files_expires_at_idx ON files (expires_at);
CREATE INDEX files_owner_name_idx ON files (owner_user_id, name);

CREATE TABLE bots (
    id         INTEGER PRIMARY KEY,
    discord_id TEXT,
    created_at TEXT NOT NULL
);

CREATE TABLE chunks (
    file_id    TEXT NOT NULL REFERENCES files (id) ON DELETE CASCADE,
    idx        INTEGER NOT NULL,
    message_id TEXT NOT NULL,
    bot_id     INTEGER REFERENCES bots (id),
    PRIMARY KEY (file_id, idx)
);

CREATE TABLE chunk_store (
    hash       TEXT PRIMARY KEY,
    message_id TEXT NOT NULL,
    size       INTEGER NOT NULL,
    created_at TEXT NOT NULL,
    bot_id     INTEGER REFERENCES bots (id)
);

CREATE INDEX chunk_store_message_idx ON chunk_store (message_id);

CREATE TABLE file_visitors (
    file_id      TEXT NOT NULL REFERENCES files (id) ON DELETE CASCADE,
    visitor_hash TEXT NOT NULL,
    first_seen   TEXT NOT NULL,
    PRIMARY KEY (file_id, visitor_hash)
);

CREATE TABLE upload_sessions (
    id                 TEXT PRIMARY KEY,
    owner_user_id      TEXT REFERENCES users (id) ON DELETE SET NULL,
    resume_token_hash  TEXT NOT NULL,
    file_name          TEXT NOT NULL,
    file_size          INTEGER NOT NULL CHECK (file_size > 0),
    chunk_size         INTEGER NOT NULL,
    chunk_count        INTEGER NOT NULL CHECK (chunk_count > 0),
    status             TEXT NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'uploading', 'completing', 'completed', 'cancelled', 'expired')),
    file_id            TEXT REFERENCES files (id) ON DELETE SET NULL,
    client_fingerprint TEXT NOT NULL DEFAULT '',
    created_at         TEXT NOT NULL,
    updated_at         TEXT NOT NULL,
    expires_at         TEXT NOT NULL
);

CREATE INDEX upload_sessions_expires_idx ON upload_sessions (expires_at)
    WHERE status IN ('pending', 'uploading');
CREATE INDEX upload_sessions_owner_idx ON upload_sessions (owner_user_id, created_at DESC);

CREATE TABLE upload_session_parts (
    upload_id  TEXT NOT NULL REFERENCES upload_sessions (id) ON DELETE CASCADE,
    idx        INTEGER NOT NULL,
    chunk_hash TEXT,
    PRIMARY KEY (upload_id, idx)
);

CREATE TABLE api_tokens (
    id           TEXT PRIMARY KEY,
    user_id      TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name         TEXT NOT NULL,
    token_hash   TEXT NOT NULL,
    scopes       TEXT NOT NULL, -- JSON array of scope strings
    expires_at   TEXT,
    revoked_at   TEXT,
    last_used_at TEXT,
    created_at   TEXT NOT NULL
);

CREATE UNIQUE INDEX api_tokens_hash_idx ON api_tokens (token_hash);
CREATE INDEX api_tokens_user_idx ON api_tokens (user_id, created_at DESC);
